# Handbuch auf den Stand der Version 149 bringen (genaue Ersetzungen; jede Fundstelle muss genau einmal vorkommen)
p = "/home/claude/eberle-buero/static/hilfe/handbuch.html"
s = open(p, encoding="utf-8").read()
n = 0
def ers(alt, neu):
    global s, n
    assert s.count(alt) == 1, (s.count(alt), alt[:90])
    s = s.replace(alt, neu); n += 1
def nach(anker, neu):   # hinter dem Anker einfügen
    ers(anker, anker + neu)

# --- 2 Bedienung: Zahlen eingeben
nach("Einen Speichern-Knopf gibt es nur dort, wo mehrere Einstellungen gemeinsam übernommen werden, etwa in den Einstellungen.</p>",
     "\n<p id=\"zahlen\"><b>Zahlen eingeben.</b> Zahlen werden in deutscher Schreibweise mit Komma eingegeben, zum Beispiel 12,5 oder 1.234,56. Ein Punkt vor genau drei Ziffern gilt als Tausenderpunkt: „1.500“ wird als 1.500 gelesen, und das Programm weist beim Verlassen des Feldes darauf hin; für Nachkommastellen steht ein Komma. Leerzeichen, „€“ und „%“ dürfen dabeistehen. Lässt sich eine Eingabe nicht als Zahl lesen (zum Beispiel „12x“), wird sie nicht gespeichert: Das Feld wird rot markiert und eine Meldung nennt die Eingabe; gespeichert bleibt der letzte lesbare Stand. Geldbeträge rundet das Programm überall kaufmännisch (halbe Cent aufwärts).</p>")

# --- 7 Belege: Druckeinstellungen
ers("Die Einstellung „Übertrag“ steht bei den Druckeinstellungen des Belegs unter Gestaltung und ist bei Belegen mit Preisen eingeschaltet.",
    "Die Einstellung „Übertrag“ steht bei den Druckeinstellungen des Belegs unter Gestaltung und ist bei Belegen mit Preisen eingeschaltet; die Vorgabe für neue und offene Belege lässt sich unter <span class=\"weg\">Einstellungen › Belege &amp; Briefbogen › Übertrag</span> abschalten.")
nach("Schon festgeschriebene Rechnungen behalten ihr bisheriges Druckbild ohne Übertrag.</p>",
     "\n<p id=\"seitenumbruch\"><b>Seitenumbruch.</b> Positionen mit bis zu sechs Textzeilen werden nicht über zwei Seiten geteilt. Längere Positionen dürfen bei „Platz optimieren“ umbrechen; dabei bleiben mindestens drei Zeilen zusammen.</p>"
     "\n<p id=\"rundung\"><b>Bruttopreise und Rundung.</b> Bei Kunden mit Preisanzeige „brutto“ zeigt jede Zeile ihren gerundeten Bruttobetrag, die Umsatzsteuer wird aber aus der Nettosumme des ganzen Belegs gerechnet. Wer die Zeilen addiert, kommt deshalb gelegentlich um einzelne Cent auf einen anderen Betrag: Drei Positionen zu je 8,40 € netto stehen mit dreimal 10,00 € im Beleg, der Gesamtbetrag lautet 29,99 €. In diesem Fall druckt der Beleg über dem Gesamtbetrag zwei erklärende Zeilen, „Summe der Einzelbeträge“ und „Rundungsdifferenz (Umsatzsteuer aus der Nettosumme)“. Schon festgeschriebene Rechnungen behalten ihr Druckbild.</p>")

# --- 7 Belege: PDF, Drucken, versandte Fassungen
nach("Die AGB werden als Original-PDF angehängt, dadurch bleibt die Datei klein.</p>",
     "\n<p>„PDF ansehen“ zeigt bei festgeschriebenen Rechnungen die Datei aus dem Archiv, also genau das Original, das auch per E-Mail hinausgeht; bei allen anderen Belegen wird das PDF aus dem aktuellen Stand neu erzeugt.</p>"
     "\n<p id=\"drucken\"><b>Drucken.</b> „Drucken“ öffnet eine Druckansicht mit dem PDF des Programms und ruft das Druckfenster des Browsers auf. Gedruckt wird damit dieselbe Datei wie bei „PDF ansehen“ und im E-Mail-Anhang, mit Briefbogen, Seitenzahlen, Übertrag und angehängten AGB. Im Druckfenster die Größe „Tatsächliche Größe“ bzw. 100 % wählen. Öffnet sich das Druckfenster nicht von selbst, löst die Schaltfläche „Drucken“ oben in der Ansicht den Druck aus. Lässt sich das PDF ausnahmsweise nicht erzeugen, erscheint stattdessen die Bildschirmfassung des Belegs mit einem roten Hinweis und wird gedruckt; ihr fehlen Seitenzahlen und Übertrag. Mahnungen werden auf demselben Weg gedruckt.</p>")
nach("Die Mail geht als HTML mit anklickbaren Adressen und zusätzlich als reiner Text hinaus.</p>",
     "\n<p id=\"versandt\"><b>Versandte Fassungen.</b> Angebote, Auftragsbestätigungen und andere noch änderbare Belege dürfen auch nach dem Versand bearbeitet werden. Damit trotzdem feststeht, was der Kunde erhalten hat, hält das Programm bei jedem Versand (per E-Mail oder „Als versendet vermerken“) die versandte Fassung als eigene PDF-Datei fest. Unter den Schaltflächen des Belegs steht dann „Versandte Fassungen“ mit Datum und Uhrzeit; ein Klick öffnet die jeweilige Datei. Ein versandter Beleg lässt sich nicht mehr löschen; soll er nicht mehr gelten, wird der Auftrag auf „Abgesagt“ gesetzt oder ein neuer Beleg erstellt. Jede gesendete E-Mail legt das Programm außerdem vollständig (mit Anhängen) im Datenordner unter „mails“ ab und verknüpft sie mit dem Eintrag in der Korrespondenz. Der Versand steht im Protokoll, und die Belegprüfung meldet, wenn eine versandte Fassung fehlt oder verändert wurde. Festgeschriebene Rechnungen brauchen das nicht, ihr Archiv-PDF ist ohnehin unveränderlich.</p>")

# --- 8 Buchhaltung: Barzahlung, Kontoauszüge
nach("Zahlungen aus dem Kontoauszug werden ohne Rückfrage übernommen.</p>",
     "\n<p><b>Barzahlungen.</b> Bei der Zahlart „Bar“ erinnert der Dialog daran, dass das Programm kein Kassenbuch führt. Wer Bargeld annimmt, führt das Kassenbuch außerhalb des Programms (täglich, lückenlos, mit Kassenbestand) und trägt das in der Verfahrensdokumentation ein.</p>")
ers("Überschneiden sich zwei Auszüge (z. B. Tagesauszug und Monatsauszug), erkennt das Programm die schon vorhandenen Umsätze und legt sie nicht doppelt an.",
    "Überschneiden sich zwei Auszüge (z. B. Tagesauszug und Monatsauszug), erkennt das Programm die schon vorhandenen Umsätze und legt sie nicht doppelt an; verglichen werden Konto, Buchungstag, Betrag und die Referenz der Bank, bei Platzhaltern wie „NONREF“ stattdessen Name und Verwendungszweck.")
nach("Die Originaldatei wird im Datenordner unter „bank“ aufbewahrt, der Kontostand am Ende des Auszugs wird übernommen.</p>",
     "\n<p id=\"auszug-hinweise\"><b>Hinweise zum Auszug.</b> Beim Einlesen prüft das Programm, ob der Auszug vollständig und plausibel ist, und zeigt Auffälligkeiten als Hinweis mit ⚠ bei der Datei unter „Eingelesene Dateien“ (die Kopfzeile des Kastens nennt, wie viele Dateien einen Hinweis haben): der Auszug gehört zu einem anderen Konto als der in den Einstellungen hinterlegten Bankverbindung; zwischen dem letzten Kontostand und dem Anfangssaldo des neuen Auszugs fehlt etwas (ein Auszug wurde ausgelassen); die Umsätze ergeben zusammen nicht den Endsaldo (die Datei ist unvollständig); ein Umsatz lautet auf eine andere Währung als Euro. Die Umsätze werden trotzdem eingelesen; die Hinweise bleiben bei der Datei stehen und stehen auch im Protokoll.</p>")
ers("Eindeutige Vorschläge sind grün mit „sicher“ markiert und lassen sich mit „Alle sicheren übernehmen“ auf einmal buchen; „prüfen“ heißt, dass nur ein Teil passt.",
    "Eindeutige Vorschläge sind grün mit „sicher“ markiert und lassen sich mit „Alle sicheren übernehmen“ auf einmal buchen; „prüfen“ heißt, dass nur ein Teil passt. Bei der Sammelübernahme wird jeder Vorschlag unmittelbar vor dem Buchen neu geprüft, und ein offener Posten oder Zahlungsauftrag wird in einem Durchgang nur einmal als sicher gebucht; passen zwei Umsätze zur selben Rechnung, hat der Umsatz mit der Rechnungsnummer Vorrang und der andere bleibt zum Prüfen stehen.")

# --- 12 Lager: Preise einlesen
ers("Tabellen dürfen Preise in deutscher, englischer oder Schweizer Schreibweise enthalten (1.234,56 · 1,234.56 · 1'234.56) und englische Spaltenüberschriften haben; erkennt das Programm die Spalten nicht, bietet es die Zuordnung von Hand an.",
    "Tabellen dürfen Preise in deutscher, englischer oder Schweizer Schreibweise enthalten (1.234,56 · 1,234.56 · 1'234.56) und englische Spaltenüberschriften haben; erkennt das Programm die Spalten nicht, bietet es die Zuordnung von Hand an. Welche Schreibweise gilt, entscheidet das Programm für die ganze Preisspalte: Ein Preis wie „1.250“ ist für sich nicht eindeutig (1.250 oder 1,25) und wird nach den übrigen Preisen der Spalte gelesen; bleibt es unklar, steht das als Hinweis über der Vorschau. Dort steht auch, wie viele Zeilen übersprungen wurden, weil der Preis fehlt, nicht lesbar oder negativ ist. Währungszeichen und „EUR“ vor oder hinter dem Preis stören nicht. Gelesen werden auch Excel-Exporte als „Unicode-Text“ und Dateien mit alten Zeilenenden; was sich nicht lesen lässt (zum Beispiel eine beschädigte Datei), weist das Programm mit einer Meldung ab.")

# --- 14 Mitarbeiter: Zeiten, Lohn, Stempeluhr
nach("Zeiten ohne Auftrag laufen über die unproduktiven Tätigkeiten (Einstellungen › Kalkulation › Unproduktive Tätigkeiten).</p>",
     "\n<p id=\"zeit-hinweise\"><b>Hinweise und Sperren.</b> Die Tagesübersicht weist auf fehlende Pausen (mehr als sechs bzw. neun Stunden), auf mehr als zehn Stunden Arbeitszeit und auf eine Ruhezeit von weniger als elf Stunden zum vorigen Arbeitstag hin. Gestempelte Zeiten, die deutlich später beim Programm ankommen als die gestempelte Uhrzeit (mehr als 15 Minuten, zum Beispiel weil das Handy keine Verbindung hatte oder ein Feierabend nachgetragen wurde), tragen in der Liste den Vermerk „⏱ nachträglich“ mit dem Zeitpunkt des Eingangs. Stempelungen, die mehr als sieben Tage zurückliegen, nimmt das Programm nicht an; solche Zeiten trägt das Büro nach. Sind für einen Monat schon Lohnzahlungen angelegt, ist er für die Stempeluhr gesperrt, und das Büro wird vor jeder Änderung oder Löschung in diesem Monat gefragt, ob sie trotzdem gelten soll.</p>")
nach("Sozialversicherung an die Krankenkasse (fällig am drittletzten Bankarbeitstag), die dann wie alle Zahlungen per SEPA-Datei überwiesen werden.</p>",
     "\n<p><b>Hinweise zum Lohn.</b> In der Liste erscheint bei einem Mitarbeiter ein ⚠, wenn der Stundenlohn (oder das Gehalt, geteilt durch die Sollstunden des Monats) unter dem gesetzlichen Mindestlohn liegt oder wenn bei einem Minijob Stundenlohn mal Iststunden die monatliche Verdienstgrenze überschreitet. Das sind Hinweise aus den Angaben im Mitarbeiterstamm, keine Lohnabrechnung; die im Programm hinterlegten Sätze gelten für die Jahre 2024 bis 2027 und werden mit Programmaktualisierungen fortgeschrieben.</p>")
ers("Ist das Handy nicht im WLAN, speichert die Stempeluhr die Buchungen und überträgt sie, sobald das WLAN wieder da ist.",
    "Ist das Handy nicht im WLAN, speichert die Stempeluhr die Buchungen und überträgt sie, sobald das WLAN wieder da ist; im Büro sind sie dann als „nachträglich“ gekennzeichnet (siehe <a href=\"#zeit-hinweise\">Hinweise und Sperren</a>). Buchungen, die älter als sieben Tage sind oder in einen schon abgerechneten Monat fallen, lehnt das Programm ab und zeigt das auf dem Handy an.")

